from format_lecon import Lesson,paras,table,steps
from diagnostics import DIAGNOSTICS
def make(n):return Lesson(DIAGNOSTICS[n-1][0],n)

l=make(7)
l.add('Une paralysie laryngée est une perte de commande motrice d’un ou des deux plis vocaux. La {distinction entre immobilité et paralysie} est indispensable avant d’en rechercher la cause.',paras('L’examen constate d’abord une mobilité réduite ou absente. Cette constatation peut résulter d’une atteinte nerveuse, mais aussi d’une fixation articulaire, d’une cicatrice ou d’une infiltration tumorale.', 'La latéralité et la position des plis déterminent les conséquences sur voix, respiration et déglutition. Une paralysie n’est donc pas définie par une voix rauque seule.'),(4,6,7))
l.add('Les causes comprennent lésions postopératoires, compressions et maladies neurologiques. Les {contextes étiologiques} doivent être recherchés sans déclarer trop vite une forme idiopathique.',paras('Le lien temporel avec chirurgie cervicale ou thoracique, intubation ou traumatisme est important. Une cause tumorale sur le trajet nerveux doit être envisagée lorsqu’aucune explication n’est évidente.', 'Une atteinte centrale ou plus étendue du nerf vague peut associer d’autres signes. Les sources suisses lues ne donnent pas de distribution chiffrée applicable à toutes les paralysies ; une cause inconnue après un bilan incomplet n’est pas une cause idiopathique établie.'),(4,6,7))
l.add('Le nerf récurrent commande l’essentiel de la motricité intrinsèque laryngée. Les {trajets nerveux et conséquences} expliquent le bilan cervical et thoracique.',paras('Le récurrent est une branche du vague ; à gauche, son trajet passe dans le thorax avant de remonter vers le larynx. Une anomalie éloignée des cordes vocales peut ainsi provoquer leur immobilité. L’innervation laryngée n’est pas réductible au seul nerf laryngé supérieur.', 'Une fermeture unilatérale insuffisante laisse fuir l’air et peut altérer la protection lors de la déglutition. Une immobilité bilatérale proche de la ligne médiane peut au contraire préserver une voix acceptable tout en limitant dangereusement l’inspiration. Une forme bilatérale plus ouverte peut surtout perturber fermeture et déglutition.'),(6,7))
l.add('La forme bilatérale peut menacer les voies aériennes malgré une voix conservée. Les {priorités spécifiques} sont la respiration, les fausses routes et la recherche de la cause.',table(['🚩 Priorité','Signe','Conduite'],[['Obstruction bilatérale.','Stridor, tirage ou dyspnée inspiratoire.','Équipe experte des voies aériennes ; une ouverture chirurgicale peut être nécessaire selon la situation.'],['Protection laryngée insuffisante.','Toux aux liquides, fausses routes, encombrement.','Évaluer déglutition et complications respiratoires.'],['Cause neurologique aiguë.','Autres déficits d’apparition soudaine.','Filière neurologique urgente.'],['Cause compressive ou tumorale.','Paralysie inexpliquée, masse ou autres signes concordants.','Bilan du trajet nerveux sans attendre une éventuelle récupération spontanée.']]),(4,6,7))
l.add('La chronologie et les symptômes associés orientent la localisation. Les {questions étiologiques} examinent les gestes récents autant que les causes spontanées.',paras('Demander chirurgie thyroïdienne, cervicale, thoracique ou de la base du crâne, intubation et traumatisme. Préciser le moment exact du changement vocal, la toux aux liquides et l’essoufflement.', 'Rechercher douleur, masse, perte de poids, troubles de l’articulation, fatigabilité et autres déficits neurologiques. Documenter les capacités alimentaires et professionnelles ; le handicap peut justifier une intervention fonctionnelle pendant que la cause est explorée.'),(4,6,7))
l.add('L’examen dynamique observe l’ouverture respiratoire et la fermeture phonatoire des deux côtés. Les {éléments de localisation} complètent la constatation d’immobilité.',paras('Décrire latéralité, position, fermeture et état de la muqueuse. Rechercher une lésion susceptible de fixer le pli plutôt qu’une neuropathie. Examiner cou, voile, langue et autres fonctions neurologiques selon les signes.', 'La stroboscopie étudie la vibration mais n’est pas nécessaire pour constater une immobilité. La sécurité de déglutition peut demander une évaluation spécialisée distincte de l’examen vocal.'),(6,7))
l.add('Le syndrome dépend de la position et de la latéralité des plis. Les {profils fonctionnels} doivent être décrits avant de choisir un geste.',table(['Profil','Fonction principalement menacée'],[['Unilatéral avec défaut de fermeture.','Voix soufflée, endurance et parfois déglutition.'],['Bilatéral avec ouverture insuffisante.','Respiration, même si la voix paraît bonne.'],['Bilatéral avec fermeture insuffisante.','Voix et protection contre les fausses routes.'],['Atteinte de plusieurs nerfs crâniens.','Cause neurologique ou du trajet proximal à localiser.']]),(4,6,7))
l.add('La confirmation comporte deux étapes : constater l’immobilité puis préciser son mécanisme. Les {critères et limites} évitent une conclusion étiologique prématurée.',paras('L’examen dynamique établit le trouble de mobilité. L’EMG peut contribuer à distinguer atteinte neuromusculaire et fixation dans certaines situations ; l’exploration articulaire ou l’imagerie répondent à d’autres questions.', 'Une origine postopératoire plausible doit être confrontée au geste et aux constatations. Une cause dite idiopathique suppose un bilan adapté négatif et un suivi, pas seulement l’absence de masse visible au larynx.'),(6,7))
l.add('Le bilan recherche une cause sur le trajet nerveux et évalue les fonctions atteintes. Les {examens selon la question} ne sont pas interchangeables.',paras('9.a — Référence pour la mobilité : laryngoscopie dynamique ; la confirmation du mécanisme nerveux peut nécessiter des examens ciblés.', '9.b — Première intention : examen laryngé, clinique cervicale et neurologique, appréciation de la déglutition si nécessaire.', '9.c — Une paralysie inexpliquée justifie une imagerie adaptée du trajet, de la base du crâne au thorax selon le contexte. Le choix entre TDM et IRM dépend de la localisation suspectée et des contraintes du patient.', '9.d — EMG dans les indications spécialisées, exploration d’une fixation si doute, bilan de déglutition selon les symptômes. Une échographie thyroïdienne seule n’explore pas tout le trajet du vague et du récurrent.'),(6,7))
l.add('L’{algorithme de la paralysie} distingue l’urgence fonctionnelle du bilan causal. Une récupération possible ne justifie pas de différer ce bilan.',steps('Décrire l’ouverture et la latéralité ; traiter en urgence une obstruction.', 'Évaluer les fausses routes et protéger alimentation et respiration selon les résultats.', 'Distinguer neuropathie et fixation, puis rechercher une cause postopératoire, compressive ou neurologique.', 'Proposer rééducation et, selon le déficit, un geste fonctionnel spécialisé.', 'Réévaluer mobilité, déglutition et handicap ; adapter le traitement à l’évolution sans perdre le suivi de la cause.'),(4,6,7))
l.add('Le traitement dépend de la fonction menacée et de la possibilité de récupération. Les {options et compromis} sont différents pour une fuite glottique et pour une obstruction.',paras('11.A — Sécuriser respiration et déglutition, traiter la cause et restaurer une communication utile.', '11.B — Une obstruction bilatérale peut nécessiter une intervention sur les voies aériennes, y compris une trachéotomie selon la situation. Pour une insuffisance unilatérale, la logopédie et des gestes de médialisation, dont certaines injections spécialisées, peuvent améliorer la fermeture. Les matériaux, volumes et délais relèvent d’une indication spécialisée ; ils ne sont pas extrapolés ici.', '11.C — Les HUG mentionnent la possibilité d’une récupération au cours des mois suivant certaines atteintes. Cela n’autorise ni l’attente sans bilan causal ni le maintien de fausses routes dangereuses. Contrôler mobilité, résultat vocal, déglutition et éventuels effets du geste.', '11.D — Expliquer les compromis : améliorer l’ouverture peut modifier la voix, tandis que rapprocher un pli doit tenir compte de la respiration. Prévoir suivi étiologique, rééducation et consignes adaptées aux symptômes.'),(4,6,7))
l.add('La prévention porte sur la reconnaissance précoce des complications et la limitation du handicap. Les {mesures selon le contexte} accompagnent le traitement de la cause.',paras('Primaire : prévention des lésions nerveuses dans les gestes à risque par les équipes concernées, sans garantie absolue. Secondaire : explorer rapidement une modification vocale ou respiratoire après chirurgie ou intubation. Tertiaire : prévenir les complications des fausses routes, maintenir la rééducation et suivre la cause ainsi que la récupération.'),(4,6,7))
l.add('Une immobilité n’est pas nécessairement une paralysie nerveuse. La bilatéralité peut menacer la respiration avec une voix conservée. La déglutition et le trajet nerveux doivent être évalués. Une récupération possible ne remplace pas le bilan causal.',refs=(4,6,7))
l.quiz([('Immobilité et paralysie sont-elles synonymes ?','Non : une fixation articulaire, cicatricielle ou tumorale peut immobiliser un pli.'),('Quel nerf assure l’essentiel de la motricité intrinsèque ?','Le nerf récurrent, branche du vague.'),('Pourquoi le thorax peut-il être exploré ?','Une partie du trajet nerveux, notamment à gauche, s’y trouve.'),('Une bonne voix exclut-elle une paralysie bilatérale dangereuse ?','Non : l’ouverture respiratoire peut être très limitée malgré une fermeture phonatoire utile.'),('Une voix soufflée évoque-t-elle une fermeture inefficace ?','Oui : une fuite glottique peut en être le mécanisme.'),('Pourquoi demander la toux aux liquides ?','Elle peut signaler des fausses routes et orienter un bilan de déglutition.'),('La stroboscopie est-elle indispensable pour constater l’immobilité ?','Non : l’examen dynamique permet cette constatation.'),('Une échographie thyroïdienne explore-t-elle tout le trajet ?','Non : elle ne remplace pas l’imagerie adaptée du trajet nerveux.'),('L’EMG est-elle systématique pour toute voix rauque ?','Non : elle répond à des indications spécialisées.'),('Peut-on attendre la récupération avant de chercher une tumeur ?','Non : la possibilité de récupération ne dispense pas du bilan causal.'),('Une chirurgie récente prouve-t-elle le mécanisme nerveux ?','Non : elle oriente, mais une lésion mécanique ou une fixation restent possibles.'),('Une médialisation vise-t-elle l’ouverture inspiratoire ?','Non : elle vise surtout à améliorer la fermeture glottique déficiente.'),('Le traitement de l’obstruction peut-il modifier la voix ?','Oui : les objectifs respiratoires et vocaux peuvent nécessiter un compromis.'),('Quand retenir une forme idiopathique ?','Après un bilan adapté sans cause identifiée et avec un suivi organisé.')],(4,6,7))
l.write()

l=make(8)
l.add('La dystonie laryngée est un trouble neurologique de commande provoquant des contractions involontaires pendant certaines tâches vocales. Les {distinctions diagnostiques} la séparent du simple forçage et du tremblement vocal.',paras('Le terme dysphonie spasmodique est également utilisé. Les interruptions vocales dépendent du type de contractions et des tâches ; une voix peut être meilleure dans certaines circonstances sans que le trouble soit volontaire.', 'La variabilité ne prouve donc pas une origine psychologique. Une dysphonie fonctionnelle ou un tremblement peuvent ressembler à une dystonie ou s’y associer ; le bilan spécialisé doit les distinguer.'),(4,6,7))
l.add('Les sources suisses retenues décrivent une affection neurologique spécialisée sans fournir une prévalence nationale. Les {repères de contexte} concernent surtout l’évolution et les troubles moteurs associés.',paras('Demander si les interruptions sont anciennes, progressives ou fluctuantes, et si d’autres régions présentent des mouvements anormaux. Une atteinte peut être essentiellement laryngée.', 'Les situations professionnelles et sociales modifient le retentissement, mais ne démontrent pas l’origine du trouble. Aucun taux de population n’est extrapolé à partir d’un nombre de patients suivis en consultation.'),(4,7))
l.add('La dystonie perturbe la coordination motrice plutôt que la seule structure de la muqueuse. Les {formes de contraction} expliquent des manifestations vocales différentes.',paras('Des contractions excessives de fermeture peuvent donner une voix serrée avec interruptions ; des contractions inappropriées d’ouverture peuvent produire des ruptures soufflées. La description précise appartient au bilan phoniatrique.', 'Il faut distinguer ces événements d’une immobilité permanente et d’une oscillation rythmique de type tremblement. L’examen pendant plusieurs tâches est plus informatif qu’une seule photographie du larynx au repos.'),(4,6,7))
l.add('Le diagnostic de dystonie ne dispense pas de rechercher une autre maladie devant un changement inhabituel. Les {signaux de réévaluation} concernent notamment respiration, déglutition et déficits associés.',table(['🚩 Constat','Conduite'],[['Déficit neurologique soudain.','Filière urgente appropriée ; ne pas l’expliquer par une dystonie chronique.'],['Dyspnée, stridor ou fausses routes importantes.','Évaluer la fonction atteinte et une autre cause possible.'],['Lésion laryngée suspecte.','Caractérisation propre, même si les spasmes sont connus.'],['Dysphagie ou gêne respiratoire après injection de toxine.','Évaluation médicale urgente selon gravité et recherche d’un effet indésirable.']]),(4,6,7,9))
l.add('L’anamnèse compare les tâches qui déclenchent ou atténuent les ruptures. Les {questions spécialisées} décrivent aussi les effets des traitements antérieurs.',paras('Faire préciser les situations de parole, le chant, les voyelles ou séquences particulièrement gênantes et l’effort compensatoire. Demander mouvements anormaux ailleurs, tremblement et antécédents neurologiques.', 'Après injections antérieures, documenter produit exact, efficacité, durée ressentie, voix soufflée, fausses routes et autres effets indésirables. Rechercher médicaments influençant la transmission neuromusculaire avant une nouvelle proposition.'),(4,7,9))
l.add('L’examen associe observation laryngée pendant les tâches et évaluation neurologique ciblée. Les {éléments discriminants} caractérisent le spasme et ses éventuels imitateurs.',paras('Comparer parole spontanée, phonation et tâches choisies par le spécialiste pour observer le type de rupture. Rechercher une lésion muqueuse, une immobilité, un tremblement ou un forçage compensatoire.', 'L’examen neurologique est guidé par le contexte et recherche d’autres manifestations dystoniques ou motrices. Un larynx sans masse ne suffit pas à établir la dystonie : il faut une sémiologie motrice concordante.'),(4,6,7))
l.add('Le syndrome est un trouble moteur lié aux tâches vocales. Les {profils à distinguer} déterminent le choix du traitement.',table(['Profil','Interprétation'],[['Ruptures avec serrage spasmodique.','Forme à prédominance de fermeture à caractériser.'],['Ruptures soufflées liées à l’ouverture.','Forme à prédominance d’ouverture à caractériser.'],['Oscillation rythmique.','Tremblement à différencier ou à associer au diagnostic.'],['Tension continue variable avec le geste.','Dysfonction compensatoire ou fonctionnelle possible.']]),(4,6,7))
l.add('Le diagnostic est clinique spécialisé et repose sur la concordance des tâches et des signes moteurs. Les {limites des tests} évitent une confirmation artificielle.',paras('Aucun test sanguin ni score unique n’établit cette dystonie. Une évaluation phoniatrique et neurologique caractérise le phénomène et ses diagnostics différentiels.', 'L’EMG peut guider certaines injections, comme le décrivent les HUG ; elle ne constitue pas un dépistage automatique de toute dysphonie. Une réponse à la toxine contribue au suivi thérapeutique sans remplacer le diagnostic initial.'),(4,6,7))
l.add('Le bilan est surtout dynamique et spécialisé. Les {examens complémentaires orientés} recherchent les causes concurrentes et préparent éventuellement un traitement.',paras('9.a — Référence : sémiologie phoniatrique et neurologique pendant les tâches pertinentes.', '9.b — Première intention : visualisation laryngée, description des interruptions et examen moteur adapté.', '9.c — Varier les tâches selon la plainte ; une observation trop brève peut manquer le trouble.', '9.d — Examens neurologiques ou imagerie si signes associés le justifient ; EMG pour des indications spécialisées, notamment certains guidages. Il n’existe pas d’imagerie systématique démontrant une dystonie laryngée isolée.'),(4,6,7))
l.add('L’{algorithme de la dystonie} caractérise d’abord le trouble moteur. Le traitement est ensuite ajusté au bénéfice et aux effets indésirables.',steps('Confirmer une sémiologie concordante et distinguer lésion, forçage et tremblement.', 'Évaluer handicap, déglutition et comorbidités neuromusculaires.', 'Discuter une prise en charge spécialisée, dont injections ciblées de toxine selon le type de dystonie.', 'Contrôler voix, durée du bénéfice, fausses routes et respiration avant toute adaptation ou répétition.'),(4,7,9))
drug=l.subwindow('toxine','Toxine botulique : statut et sécurité',paras('Les HUG décrivent l’usage de toxine botulique dans la dysphonie spasmodique. L’information professionnelle suisse de BOTOX, autorisation 52433, ne présente pas de schéma laryngé : cet emploi est présenté ici comme hors indication. La décision, la dose, le muscle et le guidage relèvent du spécialiste ; aucune dose d’une indication cervicale ou oculaire n’est transposée.', 'Citation AIPS sur les unités :')+'<blockquote>'+paras('« Les unités de toxine botulique ne sont pas applicables à d\'autres préparations. »')+'</blockquote>'+paras('Contre-indications générales de BOTOX, citations AIPS :')+'<blockquote>'+paras('« Hypersensibilité connue à la substance active, à savoir la toxine botulique de type A, ou à l\'un des excipients selon la composition. »','« Présence d\'une infection au niveau du (des) site(s) d\'injection prévu(s). »')+'</blockquote>'+paras('Grossesse et allaitement, citations AIPS :')+'<blockquote>'+paras('« BOTOX ne doit pas être utilisé pendant la grossesse ou chez des femmes en âge de procréer qui n\'utilisent pas de méthode de contraception, sauf en cas de nécessité absolue. »','« On ne sait pas si BOTOX passe dans le lait maternel. L\'utilisation de BOTOX pendant l\'allaitement ne peut pas être recommandée. »')+'</blockquote>'+paras('La fiche impose une grande prudence en cas de maladie neuromusculaire ou d’antécédents de dysphagie et d’aspiration. Des aminoglycosides, la spectinomycine et d’autres agents perturbant la transmission neuromusculaire peuvent potentialiser l’effet. Une dysphagie, une faiblesse ou un trouble respiratoire après injection nécessite une évaluation adaptée, urgente si la fonction est menacée.', 'Aucune posologie pédiatrique laryngée n’est fournie par cette information professionnelle ; ne pas extrapoler les autres indications de l’enfant. Le suivi documente le produit exact et les effets cliniques. Les modalités de prise en charge financière ne sont pas établies par cette fiche.'),(4,9))
l.add('Les injections de toxine botulique peuvent réduire les spasmes dans une prise en charge spécialisée. Les {conditions du traitement} incluent le statut hors indication et la surveillance de la déglutition.',paras('11.A — Améliorer la communication en équilibrant réduction des spasmes et faiblesse musculaire induite.', '11.B — Les HUG décrivent des injections ciblées, parfois guidées par EMG. Le choix dépend du type de dystonie ; la logopédie peut aider à réduire les compensations et adapter la communication, sans être présentée comme une guérison de la commande neurologique.')+paras(drug)+paras('11.C — Documenter bénéfice, voix soufflée, dysphagie, fausses routes et respiration. Adapter la stratégie au patient ; les doses et unités de produits différents ne sont pas interchangeables.', '11.D — Donner les signes nécessitant une consultation urgente, prévoir le suivi avant répétition et discuter les attentes réalistes. Le traitement peut demander des séances répétées ; aucune durée fixe ni dose laryngée n’est inventée.'),(4,9))
l.add('Aucune mesure simple n’est établie ici pour prévenir la survenue de la dystonie. Les {objectifs préventifs réalistes} portent sur le retard diagnostique et les conséquences du traitement.',paras('Primaire : ne pas promettre qu’une bonne technique vocale empêche une dystonie neurologique. Secondaire : reconnaître un trouble dépendant des tâches et orienter vers le bilan approprié. Tertiaire : réduire les compensations, préserver la communication et prévenir les complications des injections par sélection et surveillance adaptées.'),(4,7,9))
l.add('La variabilité selon les tâches n’implique pas une origine volontaire. Le diagnostic distingue dystonie, tremblement et forçage. Les injections relèvent d’un spécialiste avec statut et risques expliqués. Les unités ne sont pas transposables entre préparations.',refs=(4,7,9))
l.quiz([('Une voix meilleure dans certaines tâches exclut-elle une dystonie ?','Non : la dépendance aux tâches fait partie de sa sémiologie.'),('La variabilité prouve-t-elle une origine psychologique ?','Non : elle ne remplace pas l’évaluation neurologique et phoniatrique.'),('Une dystonie est-elle une immobilité permanente ?','Non : elle implique une commande inappropriée lors de certaines tâches.'),('Un tremblement et un spasme sont-ils identiques ?','Non : leur rythme et leur sémiologie doivent être distingués.'),('Pourquoi observer plusieurs tâches ?','Pour caractériser les ruptures et éviter de manquer un trouble intermittent.'),('Un larynx sans masse suffit-il au diagnostic ?','Non : il faut une sémiologie motrice concordante.'),('L’EMG est-elle un dépistage de toute dysphonie ?','Non : elle possède des indications spécialisées, dont certains guidages.'),('Les unités de toxines différentes sont-elles interchangeables ?','Non : l’AIPS précise qu’elles ne sont pas applicables aux autres préparations.'),('Peut-on reprendre la dose du torticolis pour le larynx ?','Non : aucune posologie laryngée ne doit être extrapolée d’une autre indication.'),('Le statut de BOTOX laryngé est-il documenté ici comme autorisé ?','Non : l’emploi est explicitement présenté comme hors indication dans cette fiche.'),('Quelle complication fonctionnelle surveiller après injection ?','Notamment dysphagie, fausses routes et trouble respiratoire.'),('Une myasthénie est-elle sans importance avant toxine ?','Non : une maladie neuromusculaire peut accroître la sensibilité et les risques.'),('La grossesse est-elle une situation de routine pour ce produit ?','Non : la fiche indique de ne pas l’utiliser sauf nécessité absolue et précise les précautions de contraception.'),('L’allaitement est-il recommandé avec BOTOX ?','Non : l’information professionnelle ne peut pas recommander son utilisation pendant l’allaitement.')],(4,7,9))
l.write()
